import React from'react';import Icon from'./Icons.jsx';
export function TraversePanel({data,stats,selected,onFit,onExport,onPlan,error}){const p=selected?.properties||stats.latest?.properties;return <div className="traverse-panel"><div className="rover-identity"><span className="rover-symbol"><Icon name="crosshair"/></span><div><h2>Perseverance</h2><p>Jezero Crater · recorded traverse</p></div></div><p className="traverse-description">Follow every published drive in this snapshot. Amber tracks show travelled ground; violet rings mark recorded waypoints.</p>{error&&<p className="error-message">{error}</p>}<div className="traverse-stats"><div><small>Recorded distance</small><strong>{Number.isFinite(stats.distance)?(stats.distance/1000).toFixed(2):'—'} <span>km</span></strong></div><div><small>Drive segments</small><strong>{stats.segments}</strong></div></div><button className="plan-button" onClick={onFit} disabled={!stats.segments}>Fit full traverse<Icon name="fit"/></button><div className="waypoint-inspector"><div className="eyebrow">{selected?'Selected waypoint':'Latest waypoint in range'}</div>{p?<><div className="waypoint-line"><b>Sol {p.sol}</b><span>Site {p.site} · drive {p.drive}</span></div><p>{p.Note||'Recorded rover localization'}</p><div className="waypoint-location">{(selected||stats.latest).geometry.coordinates[1].toFixed(5)}°N, {(selected||stats.latest).geometry.coordinates[0].toFixed(5)}°E</div><button className="text-action" onClick={()=>onPlan(selected||stats.latest)}>Plan a route from here <Icon name="arrow"/></button></>:<p>No recorded waypoint in this range.</p>}</div><div className="history-actions"><button onClick={onExport} disabled={!stats.segments}><Icon name="download"/>Export visible tracks</button><a href={data?.marspath_metadata.source} target="_blank" rel="noopener">Data source <Icon name="arrow"/></a></div><p className="field-note">Published snapshot through sol {data?.features?.at(-1)?.properties.sol??'…'}. Not live telemetry. HiRISE has coverage gaps; gray regional relief fills them. Routing uses the 200 m DEM.</p></div>}
export function TraverseTimeline({cut,max,stats,onChange,onAll}){return <section className="history-timeline glass" aria-label="Rover traverse timeline"><div className="timeline-heading"><span><i/>Recorded travel <b>{stats.firstSol===null?'No drives':`Sol ${stats.firstSol}–${stats.lastSol}`}</b></span><button onClick={onAll} aria-pressed={cut===max}>Show all travelled routes</button></div><div className="timeline-slider"><small>Landing</small><input type="range" min="0" max={max||1} step="1" value={cut} onChange={e=>onChange(Number(e.target.value))} aria-label="Traverse through sol"/><span>Sol {cut}</span></div></section>}
