export function validateTraverse(data){if(data?.type!=='FeatureCollection'||!Array.isArray(data.features)||!data.features.length)throw new Error('No rover drive records were supplied.');for(const f of data.features){if(f.geometry?.type!=='LineString'||f.geometry.coordinates.length<2||!Number.isFinite(f.properties?.sol)||f.geometry.coordinates.some(c=>c.length<2||!c.slice(0,2).every(Number.isFinite)||Math.abs(c[1])>90||Math.abs(c[0])>360))throw new Error('The rover traverse contains invalid geometry.')}return data}
export function visibleDrives(data,sol){return data?.features.filter(f=>f.properties.sol<=sol)||[]}
export function visibleWaypoints(data,sol){return data?.features.filter(f=>f.properties.sol<=sol)||[]}
export function traverseStats(drives,waypoints){const sols=drives.map(f=>f.properties.sol),last=waypoints.at(-1);return{segments:drives.length,firstSol:sols.length?Math.min(...sols):null,lastSol:sols.length?Math.max(...sols):null,distance:last?.properties.dist_total_m??null,latest:last}}
export function exportTraverse(data,sol){return{type:'FeatureCollection',name:'Perseverance recorded traverse',target:'Mars',coordinate_system:'Source east-positive longitude / north-positive latitude, elevation retained as published',metadata:{...data.marspath_metadata,selected_through_sol:sol,kind:'Recorded travel; not generated routes or executable rover commands'},features:visibleDrives(data,sol)}}
